function TypeCard({
  label,
  children,
  wide,
}: {
  label: string
  children: ReactNode
  wide?: boolean
}) {
  let className: string | undefined

  if (wide) {
    className = "w-full max-w-xl"
  }

  return (
    <RendersDemoCard className={className} label={label}>
      {children}
    </RendersDemoCard>
  )
}

const popoverSides = ["top", "left", "right"] as const
